package ai.interviewiq.api.service; import ai.interviewiq.api.entity.*; import org.springframework.stereotype.Service; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import java.util.*;
@Service @ConditionalOnProperty(prefix="interviewiq.ai",name="provider",havingValue="deterministic",matchIfMissing=true) class DeterministicEvaluationProvider implements EvaluationProvider { public AiEvaluation evaluate(InterviewSession s){int answered=(int)s.getQuestions().stream().filter(q->q.getAnswer()!=null).count(); double score=Math.min(100,50+(answered*10));return new AiEvaluation(score,"Temporary deterministic evaluation for local development.",List.of("Completed all required responses"),List.of("Add more measurable outcomes to answers"),List.of("Practice concise STAR-structured responses"),s.getQuestions().stream().map(q->new AiEvaluation.QuestionEvaluation(q.getId(),score,List.of("Provided a complete response"),List.of("Add concrete metrics"),"Use a concise STAR structure.")).toList());} }
